(function(){
'use strict';
var a=window.__civilTheoryCompanyModule10Parts=window.__civilTheoryCompanyModule10Parts||[];
a.push.apply(a,[
{"id":"limitada-exclusao-capital-dissolucao","title":"Exclusão de sócio, aumento/redução do capital e dissolução","basis":"CC, arts. 1.081 a 1.087 e 1.033 a 1.038","text":"A limitada possui mecanismos de recomposição interna para capital, exclusão de sócio e dissolução, sempre com proteção a minoritários e credores.","sections":[{"title":"Capital social","bullets":["Integralizadas as quotas, o capital pode ser aumentado mediante modificação do contrato e respeito ao direito de preferência dos sócios.","Pode ser reduzido por perdas irreparáveis ou quando excessivo em relação ao objeto social.","Na redução por excesso, credor quirografário com título líquido anterior pode opor-se no prazo legal de noventa dias."]},{"title":"Exclusão extrajudicial por justa causa","bullets":["Art. 1.085: exige maioria de sócios representativa de mais da metade do capital social.","Deve haver atos de inegável gravidade que ponham em risco a continuidade da empresa.","O contrato social deve prever exclusão por justa causa.","Regra geral exige reunião ou assembleia especialmente convocada e direito de defesa, ressalvada a sociedade composta por apenas dois sócios, conforme disciplina legal atual."]},{"title":"Dissolução","bullets":["Pode decorrer das hipóteses legais, contratuais ou judiciais.","Dissolução conduz à liquidação e posterior extinção após encerramento das relações patrimoniais.","Resolução em relação a um sócio não se confunde com dissolução total."]}],"table":{"headers":["Tema","Requisito-chave"],"rows":[["Aumento de capital","Quotas integralizadas + preferência"],["Redução por excesso","Possível oposição de credor por 90 dias"],["Exclusão extrajudicial","Justa causa + previsão contratual + > metade do capital"]]},"example":"Sócio pratica atos graves que comprometem a continuidade da empresa. Se o contrato prevê a exclusão e os requisitos do art. 1.085 são atendidos, pode haver exclusão extrajudicial.","trap":"Exclusão por justa causa não decorre apenas de desentendimento entre sócios; exige gravidade e requisitos legais.","memorize":["Art. 1.085: atos de inegável gravidade.","> metade do capital.","Redução por excesso: oposição do credor em 90 dias."]},
{"id":"tipos-societarios-cooperativa-sa","title":"Demais tipos societários, cooperativa e sociedade por ações","basis":"CC, arts. 1.039 a 1.051, 1.088 a 1.096; legislação especial","text":"Além da sociedade simples e limitada, o Código regula tipos com responsabilidade e estrutura próprias. Para prova, o essencial é reconhecer diferenças de responsabilidade e as exceções de classificação.","sections":[{"title":"Tipos pessoais","bullets":["Sociedade em nome coletivo é composta por pessoas físicas e envolve responsabilidade solidária e ilimitada dos sócios pelas obrigações sociais, após o patrimônio social conforme o regime legal.","Comandita simples distingue comanditados, com responsabilidade ilimitada e gestão, e comanditários, com responsabilidade limitada à quota e restrições de gestão."]},{"title":"S/A e cooperativa","bullets":["Sociedade por ações é sempre empresária, qualquer que seja seu objeto, e rege-se principalmente pela Lei 6.404/1976.","Cooperativa é sempre sociedade simples, independentemente do objeto, e possui disciplina própria complementada por legislação especial.","Comandita por ações segue regras próprias e, subsidiariamente, normas da sociedade anônima."]}],"table":{"headers":["Tipo","Ponto de prova"],"rows":[["Nome coletivo","Sócios pessoas físicas; responsabilidade ilimitada"],["Comandita simples","Comanditado x comanditário"],["S/A","Sempre empresária"],["Cooperativa","Sempre simples"]]},"example":"Uma cooperativa que explora atividade econômica organizada não se torna sociedade empresária apenas por causa da atividade; o art. 982 a classifica como simples.","trap":"Não aplique à limitada a regra de classificação automática da S/A.","memorize":["S/A sempre empresária.","Cooperativa sempre simples.","Comandita separa categorias de sócios."]},
{"id":"operacoes-societarias","title":"Transformação, incorporação, fusão, dissolução e liquidação","basis":"CC, arts. 1.102 a 1.122","text":"Operações societárias alteram estrutura, continuidade ou patrimônio das sociedades. A prova costuma exigir diferenças conceituais entre transformação, incorporação e fusão e a proteção dos credores.","sections":[{"title":"Transformação, incorporação e fusão","bullets":["Transformação muda o tipo societário sem dissolução ou liquidação da pessoa jurídica.","Incorporação: uma ou mais sociedades são absorvidas por outra, que lhes sucede em direitos e obrigações.","Fusão: sociedades se unem para formar sociedade nova que as sucede.","Cisão é disciplinada especialmente pela Lei das S/A, embora frequentemente apareça em conjunto com as demais operações."]},{"title":"Dissolução e liquidação","bullets":["Dissolução inicia processo de encerramento, mas não extingue imediatamente a personalidade para todos os efeitos.","Liquidação realiza ativo, paga passivo e apura eventual saldo.","A extinção societária ocorre após o encerramento da liquidação e registro dos atos pertinentes."]}],"table":{"headers":["Operação","Resultado"],"rows":[["Transformação","Muda o tipo"],["Incorporação","Absorção por sociedade existente"],["Fusão","Criação de sociedade nova"],["Dissolução","Inicia encerramento"],["Liquidação","Realiza ativo e paga passivo"]]},"example":"Duas sociedades deixam de existir e seus patrimônios formam uma terceira nova sociedade. A operação é fusão, não incorporação.","trap":"Transformação não exige dissolver e liquidar a sociedade anterior.","memorize":["Transformação = muda tipo.","Incorporação = absorção.","Fusão = nova sociedade.","Dissolução ≠ extinção imediata."]},
{"id":"estabelecimento-trespasse","title":"Estabelecimento empresarial e trespasse","basis":"CC, arts. 1.142 a 1.149","text":"Estabelecimento é o complexo organizado de bens para exercício da empresa e não se confunde com o local físico. Pode ser objeto unitário de negócios e sua transferência — trespasse — possui regime protetivo de credores e da continuidade empresarial.","sections":[{"title":"Estabelecimento e local","bullets":["Complexo pode conter bens corpóreos e incorpóreos.","O local da atividade pode ser físico ou virtual e não se confunde com estabelecimento.","Estabelecimento pode ser alienado, arrendado ou dado em usufruto conforme sua natureza."]},{"title":"Trespasse","bullets":["Eficácia perante terceiros exige averbação no registro mercantil e publicação.","Se não restarem bens suficientes ao alienante, exige-se pagamento dos credores ou consentimento expresso ou tácito em trinta dias da notificação.","Adquirente responde pelos débitos anteriores regularmente contabilizados; alienante permanece solidariamente obrigado por um ano nos termos do art. 1.146.","Sem autorização expressa, alienante não pode concorrer com adquirente por cinco anos.","Contratos não pessoais se sub-rogam no adquirente, salvo disposição em contrário, com possibilidade de rescisão por justa causa pelo terceiro no prazo legal."]}],"table":{"headers":["Tema","Prazo/regra"],"rows":[["Consentimento de credores","30 dias da notificação"],["Solidariedade do alienante","1 ano, conforme art. 1.146"],["Não concorrência","5 anos"],["Rescisão de contratos por justa causa","90 dias da publicação"]]},"example":"Empresa vende todo o estabelecimento e o alienante abre negócio concorrente ao lado três meses depois, sem autorização contratual. A regra do art. 1.147 impede a concorrência por cinco anos.","trap":"Estabelecimento não é sinônimo de imóvel, sede ou ponto físico; o Código expressamente admite local virtual.","memorize":["Estabelecimento = complexo de bens.","Local pode ser físico ou virtual.","Não concorrência: 5 anos.","Débitos contabilizados passam ao adquirente nos termos legais."]},
{"id":"registro-nome","title":"Registro e nome empresarial","basis":"CC, arts. 1.150 a 1.168","text":"Registro empresarial confere publicidade e oponibilidade. Nome empresarial é firma ou denominação utilizada no exercício da empresa e segue princípios de veracidade, novidade e proteção territorial.","sections":[{"title":"Registro","bullets":["Empresário e sociedade empresária vinculam-se ao Registro Público de Empresas Mercantis; sociedade simples, em regra, ao Registro Civil das Pessoas Jurídicas.","Atos apresentados em até trinta dias podem produzir efeitos conforme o regime do art. 1.151; após o prazo, o efeito registral ocorre da concessão.","Ato sujeito a registro não pode, antes das formalidades, ser oposto a terceiro, salvo prova de conhecimento."]},{"title":"Firma e denominação","bullets":["Empresário individual opera sob firma formada por seu nome.","Limitada pode adotar firma ou denominação, ambas integradas por 'limitada' ou abreviatura.","Omissão da indicação 'limitada' pode acarretar responsabilidade solidária e ilimitada dos administradores que empregarem o nome assim.","Nome empresarial deve distinguir-se de outro já inscrito no mesmo registro.","Nome empresarial não pode ser alienado isoladamente, sem prejuízo da regra de uso pelo sucessor do estabelecimento."]},{"title":"Proteção","bullets":["Inscrição assegura uso exclusivo nos limites do Estado, com extensão nacional conforme lei especial.","Ação para anular inscrição de nome empresarial feita em violação da lei ou contrato pode ser proposta a qualquer tempo.","Nome de sócio falecido, excluído ou retirante não pode permanecer na firma social."]}],"table":{"headers":["Figura","Regra"],"rows":[["Empresário individual","Firma"],["Limitada","Firma ou denominação"],["S/A","Denominação"],["SCP","Não pode ter firma ou denominação"]]},"example":"Limitada usa denominação sem a expressão 'limitada' ou 'Ltda.'. Os administradores que a empregarem podem sofrer a consequência do art. 1.158, §3º.","trap":"Nome empresarial não se confunde com marca; têm regimes e registros distintos.","memorize":["Firma ou denominação.","Limitada: deve indicar limitada/Ltda.","Proteção estadual pelo registro.","Nome empresarial é inalienável isoladamente."]},
{"id":"prepostos-escrituracao","title":"Prepostos, gerente, contabilista, escrituração e balanços","basis":"CC, arts. 1.169 a 1.195; STJ, REsp 2.002.734/SP","text":"Prepostos atuam em colaboração com o empresário e podem vincular o preponente dentro das funções exercidas. Escrituração e balanços asseguram controle patrimonial, prova e transparência, com regras próprias de sigilo e exibição.","sections":[{"title":"Prepostos e gerente","bullets":["Preposto não pode substituir-se sem autorização escrita, sob pena de responsabilidade pessoal.","Sem autorização expressa, não pode negociar por conta própria ou de terceiro em operação do mesmo gênero da incumbência.","Gerente é preposto permanente e presume-se autorizado aos atos necessários aos poderes outorgados quando a lei não exigir poderes especiais.","Limitações aos poderes do gerente precisam de arquivamento e averbação para oponibilidade, salvo prova de conhecimento do terceiro.","Preponente responde pelos atos de prepostos praticados no estabelecimento e relativos à atividade, ainda que não autorizados por escrito, nos termos do art. 1.178."]},{"title":"Escrituração","bullets":["Empresário e sociedade empresária devem manter sistema de contabilidade uniforme e levantar anualmente balanço patrimonial e de resultado econômico, ressalvado pequeno empresário nas hipóteses legais.","Livro Diário é indispensável, salvo substituições autorizadas.","Escrituração deve observar idioma e moeda nacionais, ordem cronológica e regularidade formal.","Livros empresariais possuem regime de sigilo relativo e podem ser exibidos nos casos legais."]},{"title":"Jurisprudência 2026","bullets":["STJ, REsp 2.002.734/SP: sociedade limitada de grande porte não pode ser obrigada, como condição para arquivamento de atos societários, a comprovar publicação prévia de balanço anual e demonstrações financeiras em Diário Oficial e jornal de grande circulação.","Para essas limitadas de grande porte, a Lei 11.638/2007 impõe regras de escrituração, demonstrações financeiras e auditoria independente, não uma obrigação geral de publicação como condição registral."]}],"table":{"headers":["Tema","Ponto central"],"rows":[["Gerente","Poderes necessários presumidos"],["Atos no estabelecimento","Podem vincular preponente"],["Diário","Livro indispensável em regra"],["Limitada de grande porte","Publicação de balanço não é condição para arquivamento segundo STJ 2026"]]},"example":"Gerente pratica ato ordinário ligado à atividade no estabelecimento. A empresa não afasta automaticamente a vinculação alegando ausência de autorização escrita interna.","trap":"Não confunda obrigação de elaborar demonstrações financeiras com obrigação de publicá-las em jornal como condição para registrar atos de limitada de grande porte.","memorize":["Gerente = preposto permanente.","Art. 1.178 protege terceiros nos atos do estabelecimento.","Diário é indispensável em regra.","STJ 2026: publicação prévia do balanço não condiciona arquivamento da limitada de grande porte."]}
]);
})();
